<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { AlertCircle, BadgeCheck, ChevronRight, LayoutPanelTop, Play, RefreshCw, RotateCcw, ShieldCheck } from '@lucide/vue'
import { getCompetitionDemoContext, initializeCompetitionDemo, resetCompetitionDemo } from '../api'
import CompetitionDemoContextBand from '../components/CompetitionDemoContextBand.vue'

const router=useRouter(),data=ref({showcase:{journeys:[],ready_count:0,total_count:3},sources:[]}),loading=ref(false),initializing=ref(false),resetting=ref(false),error=ref(''),notice=ref('')
const hasDemoData=computed(()=>Boolean(data.value.course))
const repairRequired=computed(()=>hasDemoData.value&&!data.value.initialized)
function detail(e){const d=e?.detail;return d?.message||(typeof d==='string'?d:'')||e?.message||'操作失败'}
async function load(){loading.value=true;error.value='';try{data.value=await getCompetitionDemoContext()}catch(e){error.value=detail(e)}finally{loading.value=false}}
async function initialize(){initializing.value=true;error.value='';notice.value='';try{if(repairRequired.value){await resetCompetitionDemo();notice.value='异常演示上下文已恢复到冻结初始状态'}else{const result=await initializeCompetitionDemo();notice.value=result.seed?.status==='created'?'统一演示上下文已创建':'统一演示上下文已核验并复用'}await load()}catch(e){error.value=detail(e)}finally{initializing.value=false}}
async function reset(){resetting.value=true;error.value='';notice.value='';try{await resetCompetitionDemo();notice.value='演示数据已恢复到冻结初始状态';await load()}catch(e){error.value=detail(e)}finally{resetting.value=false}}
function openJourney(item){if(item.ready)router.push(item.route)}
onMounted(load)
</script>

<template><main class="showcase" data-testid="competition-showcase"><header><div><p class="eyebrow"><LayoutPanelTop :size="14"/> Competition demo</p><h1>比赛演示中心</h1><p>使用同一门课程、同一个 15 人班级和同一名焦点学生，进入学生、教师与技术证据三条主旅程。</p></div><button class="icon" aria-label="刷新比赛演示中心" title="刷新" @click="load"><RefreshCw :size="17"/></button></header>
<p v-if="error" class="notice error"><AlertCircle :size="15"/>{{error}}</p><p v-if="notice" class="notice ok"><BadgeCheck :size="15"/>{{notice}}</p><p v-if="loading" class="notice"><RefreshCw class="spin" :size="15"/>正在读取统一演示上下文</p>
<section v-if="data.truthfulness" class="truth"><ShieldCheck :size="18"/><div><strong>冻结合成演示数据</strong><span>课程材料来自仓库冻结文档 · {{data.truthfulness.claim_boundary}}</span></div></section>
<CompetitionDemoContextBand :context="data" page="showcase" :primary-action-label="repairRequired?'恢复冻结初始状态':''" @primary-action="initialize" />
<p v-if="repairRequired" class="notice error"><AlertCircle :size="15"/>检测到演示数据与焦点学生上下文不一致，请恢复冻结初始状态后再开始体验。</p>
<section class="summary"><div><span>主旅程就绪</span><strong>{{data.showcase?.ready_count||0}} / {{data.showcase?.total_count||3}}</strong></div><div class="bar"><i :style="{width:`${((data.showcase?.ready_count||0)/(data.showcase?.total_count||3))*100}%`}"/></div><div class="actions"><button class="secondary" :disabled="resetting||initializing||!hasDemoData" @click="reset"><RotateCcw :size="14"/>{{resetting?'正在恢复':'恢复初始状态'}}</button><button class="primary" :disabled="initializing||resetting" @click="initialize"><Play :size="14"/>{{initializing?(repairRequired?'正在恢复':'正在初始化'):(repairRequired?'恢复冻结初始状态':'一键初始化演示数据')}}</button></div></section>
<section v-if="data.course" class="context"><div><span>统一课程</span><strong>{{data.course.title}}</strong><small>{{data.course.chapter_count}} 章 · {{data.course.knowledge_point_count}} 个知识点</small></div><div><span>演示班级</span><strong>{{data.cohort?.title}}</strong><small>{{data.cohort?.student_count}} 人 · {{Math.round((data.cohort?.participation_rate||0)*100)}}% 参与率</small></div><div><span>课程来源</span><strong>{{data.course.source_count}} 份冻结文档</strong><small>许可、版本与 SHA-256 可追溯</small></div></section>
<section class="journeys"><article v-for="(item,index) in (data.showcase?.journeys||[])" :key="item.key" :class="{ready:item.ready}"><div class="num">0{{index+1}}</div><div><span>{{item.key}}</span><strong>{{item.label}}</strong><small>{{item.ready?'统一上下文已就绪':repairRequired?'需要恢复冻结初始状态':'需要先初始化演示数据'}}</small></div><button :disabled="!item.ready" @click="openJourney(item)">{{item.ready?'进入旅程':'未就绪'}}<ChevronRight :size="14"/></button></article></section>
<section class="boundary"><strong>完成口径</strong><p>初始化只建立可信起跑线，不伪造旅程完成结果。学生学习、画像变化、复习调度和教师干预仍需通过正式页面、持久化对象和权限边界完成。</p></section></main></template>

<style scoped>.showcase{max-width:1240px;margin:auto;color:#20272a;padding:4px 2px 42px}.showcase header{display:flex;justify-content:space-between;align-items:flex-start;padding:24px 2px 20px;border-bottom:1px solid #dce2e5}.showcase h1{font-size:24px;margin:6px 0;letter-spacing:0}.showcase header p:last-child{font-size:13px;color:#667177}.eyebrow{display:flex;align-items:center;gap:7px;color:#3f6659;font-size:10px;font-weight:750;text-transform:uppercase}.icon{width:36px;height:36px;display:grid;place-items:center;border:1px solid #d8dfe2;background:#fff;border-radius:7px}.notice{display:flex;align-items:center;gap:7px;padding:11px 14px;background:#f4f7f8;font-size:10px}.notice.error{background:#fff1ef;color:#963f35}.notice.ok{background:#eef8f1;color:#276046}.truth{display:flex;align-items:center;gap:10px;padding:12px 15px;background:#eef6f3;color:#31594d;border-bottom:1px solid #cddfd9}.truth div{display:flex;flex-wrap:wrap;gap:5px 14px}.truth strong{font-size:11px}.truth span{font-size:10px}.summary{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:18px;padding:18px 0;border-bottom:1px solid #dce2e5}.summary>div:first-child{display:flex;flex-direction:column}.summary span,.context span,.roles span,.journeys span{font-size:8px;color:#748087}.summary strong{font-size:18px}.bar{height:7px;background:#dce8e4}.bar i{display:block;height:100%;background:#447867}.actions{display:flex;align-items:center;gap:8px}.primary,.secondary,.journeys button{display:inline-flex;align-items:center;justify-content:center;gap:6px;border-radius:6px;padding:10px 13px;font-size:10px;font-weight:650}.primary,.journeys button{border:0}.primary{background:#315e50;color:#fff}.secondary{border:1px solid #b9cbc5;background:#fff;color:#315e50}.primary:disabled,.secondary:disabled,.journeys button:disabled{opacity:.55}.context{display:grid;grid-template-columns:1fr 1fr 1fr;background:#f8fbfa;border-bottom:1px solid #dce2e5}.context div{display:flex;flex-direction:column;gap:3px;padding:14px;border-right:1px solid #e2e8e6;min-width:0}.context strong{font-size:11px;overflow-wrap:anywhere}.context small,.roles small,.journeys small{font-size:8px;color:#748087;overflow-wrap:anywhere}.roles{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;padding:18px 0}.roles article{display:flex;gap:10px;padding:14px;border:1px solid #dce2e5;background:#fff}.roles article>div{display:flex;flex-direction:column;min-width:0}.roles strong{font-size:11px}.roles code{margin-top:5px;font-size:8px;color:#315e50}.journeys{display:grid;grid-template-columns:1fr 1fr;gap:12px}.journeys article{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px;padding:16px;border:1px solid #dce2e5;background:#fff}.journeys article.ready{border-color:#bdd3c5;background:#f4faf6}.num{font-size:20px;color:#a1abad}.journeys article.ready .num{color:#447867}.journeys article>div:nth-child(2){display:flex;flex-direction:column}.journeys strong{font-size:12px}.journeys button{background:#eaf3f0;color:#315e50}.boundary{margin-top:18px;padding:14px;border:1px solid #dce2e5;background:#f8fafb}.boundary strong{font-size:10px}.boundary p{font-size:9px;color:#667177;margin-top:4px}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:800px){.summary,.context,.roles,.journeys{grid-template-columns:1fr}.actions{display:grid;grid-template-columns:1fr 1fr}.summary .primary,.summary .secondary{width:100%}.context div{border-right:0;border-bottom:1px solid #e2e8e6}.journeys article{grid-template-columns:auto 1fr}.journeys button{grid-column:1/-1;width:100%}}@media(max-width:430px){.showcase h1{font-size:21px}.truth{align-items:flex-start}.actions{grid-template-columns:1fr}}</style>
